pipeline:
  batch_size: 125
  batch_delay: 50
  workers: 4

input {
  beats {
    port => 5044
    codec => "json"
    # 启用压缩
    client_inactivity_timeout => 3600
  }
}

filter {
  # 并行处理
  if [type] == "application" {
    # 应用特定处理
  } else if [type] == "nginx" {
    # Nginx特定处理
  }

  # 避免不必要的字段处理
  mutate {
    remove_field => ["@version", "tags", "_id"]
  }
}

output {
  elasticsearch {
    hosts => ["elasticsearch-host:9200"]
    # 批量提交优化
    flush_size => 5000
    idle_flush_time => 5
